mapper.select:
select oc.id as id,oc.create_time as createTime,oc.role_code as roleCode,oc.post_id as postId, jp.title as title,jp.phone as contact, su.nickname as userName,su.avatar as userAvatar,su.phone as phone from job_post_contact oc left join job_post jp on jp.id=oc.post_id left join sys_user su on su.id=oc.post_user_id WHERE 1=1
AND oc.user_id = #{params.userId}
AND oc.post_user_id = #{params.postUserId}
and ( jp.title like CONCAT('%',#{params.keyword},'%') or jp.descr like CONCAT('%',#{params.keyword},'%') )
order by oc.create_time desc

select oc.id as id,oc.create_time as createTime,oc.role_code as roleCode,oc.post_id as postId, jp.title as title,jp.phone as contact, su.nickname as postUserName,su.avatar as postUserAvatar,su.phone as postUserphone, su2.nickname as userName,su2.avatar as userAvatar,su2.phone as userPhone from job_post_contact oc left join job_post jp on jp.id=oc.post_id left join sys_user su on su.id=oc.post_user_id left join sys_user su2 on su2.id=oc.user_id WHERE 1=1
AND oc.user_id = #{params.userId}
AND oc.post_user_id = #{params.postUserId}
and ( jp.title like CONCAT('%',#{params.keyword},'%') or jp.descr like CONCAT('%',#{params.keyword},'%') or su.nickname like CONCAT('%',#{params.keyword},'%') or su.phone like CONCAT('%',#{params.keyword},'%') or su2.nickname like CONCAT('%',#{params.keyword},'%') or su2.phone like CONCAT('%',#{params.keyword},'%') )
order by oc.create_time desc
